    /*
    /**********************************************************
    /* Configured helper objects
    /**********************************************************
     */
    /**
     * Object used for resolving filter ids to filter instances.
     * Non-null if explicitly defined; null by default.
     */
    protected final FilterProvider _filterProvider;

    /**
